sqlGroup.select:
select a.*, b.dname as ctypeName, c.rname as provinceName, d.rname as cityName, e.rname as areaName, concat(c.rname,d.rname,e.rname) as locals, f.cname as parentName
from sys_org a left join sys_dict b on b.dval=a.ctype and b.tcode='ORG_TYPE' left join sys_region c on c.code=a.province left join sys_region d on d.code=a.city left join sys_region e on e.code=a.area left join sys_org f on f.id=a.pid
find_in_set(a.pid,getOrgChildLst(#{pid}))
and a.id = #{id}
and a.cname like '%${cname}%'
and a.ccode like '%${ccode}%'
and a.ctype = #{ctype}
and a.province = #{province}
and a.city = #{city}
and a.area = #{area}
order by a.createTime desc,a.updateTime desc
